param(
    [string]$Project = "C:\Proyectos\pdfprivado-pro"
)

$ErrorActionPreference = "Stop"
$Downloads = Join-Path $env:USERPROFILE "Downloads"
$Stamp = Get-Date -Format "yyyyMMdd-HHmmss"
$OutRoot = Join-Path $Downloads "PDFPrivado-S1B8-T6A3-GEOMETRY-SOURCE-$Stamp"
New-Item -ItemType Directory -Path $OutRoot -Force | Out-Null

$Source = Get-ChildItem -LiteralPath $Downloads -Directory |
    Where-Object { $_.Name -like "PDFPrivado-S1B7-T5-HYBRID-TABLE-SHELL-*" } |
    Sort-Object LastWriteTime -Descending |
    Where-Object {
        $Result = Join-Path $_.FullName "RESULTADO.json"
        if (-not (Test-Path -LiteralPath $Result)) { return $false }
        try {
            $Data = Get-Content -LiteralPath $Result -Raw | ConvertFrom-Json
            return ($Data.pass -eq $true)
        } catch {
            return $false
        }
    } |
    Select-Object -First 1

if (-not $Source) {
    throw "No se encontro una salida T5 PASS reutilizable."
}

$PythonCommand = Get-Command python.exe -ErrorAction SilentlyContinue
if (-not $PythonCommand) {
    $PythonCommand = Get-Command python -ErrorAction SilentlyContinue
}
if (-not $PythonCommand) {
    throw "No se encontro Python."
}
$PythonExe = $PythonCommand.Source
if (-not $PythonExe) { $PythonExe = $PythonCommand.Path }

$Driver = Join-Path $OutRoot "t6a3-geometry-source.py"
[System.IO.File]::WriteAllBytes(
    $Driver,
    [Convert]::FromBase64String("")
)

Write-Host "============================================================" -ForegroundColor Cyan
Write-Host " PDFPRIVADO PRO - S1B8-T6A3 GEOMETRY SOURCE READ-ONLY" -ForegroundColor Cyan
Write-Host "============================================================" -ForegroundColor Cyan
Write-Host "T5 permanece baseline local. No modifica DOCX ni motor." -ForegroundColor Green
Write-Host ""

& $PythonExe `
    $Driver `
    --source $Source.FullName `
    --out (Join-Path $OutRoot "RESULTADO.json")

$ExitCode = $LASTEXITCODE

if ($ExitCode -eq 0) {
    Write-Host "S1B8-T6A3 PASS." -ForegroundColor Green
} elseif ($ExitCode -eq 2) {
    Write-Host "S1B8-T6A3 gate FAIL; T5 permanece intacta." -ForegroundColor Yellow
} else {
    Write-Host "S1B8-T6A3 fallo tecnico; T5 permanece intacta." -ForegroundColor Red
}

Write-Host "No commit/tag/promocion oficial." -ForegroundColor Green
exit $ExitCode
